"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41861"],{75640(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cascata_fora_do_regime_federal","status":422,"titulo":"Uma modalidade SegueCascata est\xe1 numa oferta que n\xe3o usa regra de distribui\xe7\xe3o do ramo federal (Lei 12.711)"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cascata_fora_do_regime_federal","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["Uma oferta de curso tem modalidade com `regraRemanejamento` igual a\\n`SEGUE_ORDEM_DE_REMANEJAMENTO`, mas a oferta n\xe3o usa a regra de distribui\xe7\xe3o de vagas da\\nLei 12.711/2012 (cascata de remanejamento de cotas, UNI-REQ-0056). A cascata do processo \xe9 a sequ\xeancia legal\\nde remanejamento das cotas reservadas dessa lei \u2014 fora desse regime, n\xe3o\\nh\xe1 reserva legal cuja vaga n\xe3o preenchida precise ser remanejada por uma\\nsequ\xeancia congelada; `SEGUE_ORDEM_DE_REMANEJAMENTO` n\xe3o tem o que resolver ali.","Roda como parte da confer\xeancia de conformidade estrutural para publica\xe7\xe3o\\n(`PendenciaDaCascata`), avaliada oferta por oferta, em ordem determin\xedstica\\n(por `OfertaCursoOrigemId`). \xc9 a primeira condi\xe7\xe3o conferida para cada\\noferta com ao menos uma modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` \u2014 antes de checar se o\\nprocesso tem cascata configurada. Sequencial: a primeira oferta com essa\\ninconsist\xeancia interrompe a avalia\xe7\xe3o; nunca acumula com nenhuma outra\\ncausa desta s\xe9rie."],"comoResolver":["Se a modalidade de fato pertence a uma cota reservada da Lei 12.711/2012,\\nconfirme que a oferta est\xe1 configurada com a regra de distribui\xe7\xe3o de\\nvagas correspondente. Se a oferta n\xe3o segue esse regime, corrija o\\n`remanejamento.regra` da modalidade para `DESTINO_UNICO` ou `CRUZADO`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);